13	// DEVDESK-342: `mise run ci` replays the CI workflow locally. It must chain,
14	// sequentially and in order, exactly the `mise run <task>` steps of ci.yml, so
15	// the two cannot drift apart. mise.toml is read without a TOML library (none is
16	// in go.mod): the guard only needs the task headers, the description and the
17	// `run = [{ task = "..." }, ...]` array of [tasks.ci].
18	
19	var ciSteps = []string{"fmt-check", "vet", "lint", "build", "test", "test-race"}
20	
21	var (
22		taskHeaderRe = regexp.MustCompile(`(?m)^\[tasks\.([A-Za-z0-9_.-]+)\]\s*$`)
23		sectionRe    = regexp.MustCompile(`(?m)^\[`)
24		stepRe       = regexp.MustCompile(`task\s*=\s*"([^"]+)"`)
25	)
26	
27	// miseSection returns the body of [tasks.<name>] and the set of all task names.
28	func miseSection(t *testing.T, name string) (body string, all map[string]bool) {
29		t.Helper()
30		raw, err := os.ReadFile(filepath.Join(moduleRoot(t), "mise.toml"))
31		if err != nil {
32			t.Fatal(err)
33		}
34		src := string(raw)
35		all = map[string]bool{}
36		for _, m := range taskHeaderRe.FindAllStringSubmatch(src, -1) {
37			all[m[1]] = true
38		}
39		loc := regexp.MustCompile(`(?m)^\[tasks\.` + regexp.QuoteMeta(name) + `\]\s*$`).FindStringIndex(src)
40		if loc == nil {
41			return "", all
42		}
43		rest := src[loc[1]:]
44		if next := sectionRe.FindStringIndex(rest); next != nil {
45			rest = rest[:next[0]]
46		}
47		return rest, all
48	}
49	
50	func ciTaskBody(t *testing.T) (string, map[string]bool) {
51		t.Helper()
52		body, all := miseSection(t, "ci")
53		if body == "" {
54			t.Fatal("mise.toml has no [tasks.ci] section (DEVDESK-342)")
55		}
56		return body, all
57	}
58	
59	func ciRunSteps(t *testing.T, body string) []string {
60		t.Helper()
61		var steps []string
62		for _, m := range stepRe.FindAllStringSubmatch(body, -1) {
63			steps = append(steps, m[1])
64		}
65		return steps
66	}
67	
68	func TestMiseCIHasDescriptionMentioningCIAndCheck(t *testing.T) {
69		body, _ := ciTaskBody(t)
70		m := regexp.MustCompile(`(?m)^description\s*=\s*"((?:[^"\\]|\\.)*)"`).FindStringSubmatch(body)
71		if m == nil || strings.TrimSpace(m[1]) == "" {
72			t.Fatal("[tasks.ci] needs a non-empty description")
73		}
74		d := strings.ToLower(m[1])
75		if !strings.Contains(d, "ci") {
76			t.Errorf("description %q must say it reproduces the CI", m[1])
77		}
78		if !strings.Contains(d, "check") {
79			t.Errorf("description %q must say how it differs from `check`", m[1])
80		}
81	}
82	
83	func TestMiseCIRunsStepsSequentiallyInOrder(t *testing.T) {
84		body, _ := ciTaskBody(t)
85		if regexp.MustCompile(`(?m)^depends\w*\s*=`).MatchString(body) {
86			t.Error("[tasks.ci] must not use depends/depends_post: mise runs those in parallel")
87		}
88		got := ciRunSteps(t, body)
89		if strings.Join(got, ",") != strings.Join(ciSteps, ",") {
90			t.Errorf("[tasks.ci] run steps = %v, want %v", got, ciSteps)
91		}
92	}
93	
94	func TestMiseCIMatchesWorkflowSteps(t *testing.T) {
95		raw, err := os.ReadFile(filepath.Join(moduleRoot(t), ".github", "workflows", "ci.yml"))
96		if err != nil {
97			t.Fatal(err)
98		}
99		var wf struct {
100			Jobs map[string]struct {
101				Steps []struct {
102					Run string `yaml:"run"`
103				} `yaml:"steps"`
104			} `yaml:"jobs"`
105		}
106		if err := yaml.Unmarshal(raw, &wf); err != nil {
107			t.Fatal(err)
108		}
109		// Job order is not preserved by a map: walk the two jobs in file order.
110		var order yaml.Node
111		if err := yaml.Unmarshal(raw, &order); err != nil {
112			t.Fatal(err)
113		}
114		var jobNames []string
115		for i := 0; i+1 < len(order.Content[0].Content); i += 2 {
116			if order.Content[0].Content[i].Value != "jobs" {
117				continue
118			}
119			jobs := order.Content[0].Content[i+1]
120			for j := 0; j+1 < len(jobs.Content); j += 2 {
121				jobNames = append(jobNames, jobs.Content[j].Value)
122			}
123		}
124		var fromCI []string
125		for _, name := range jobNames {
126			for _, s := range wf.Jobs[name].Steps {
127				if task, ok := strings.CutPrefix(strings.TrimSpace(s.Run), "mise run "); ok {
128					fromCI = append(fromCI, strings.TrimSpace(task))
129				}
130			}
131		}
132		if strings.Join(fromCI, ",") != strings.Join(ciSteps, ",") {
133			t.Fatalf("ci.yml `mise run` steps = %v, want %v", fromCI, ciSteps)
134		}
135		body, _ := ciTaskBody(t)
136		if got := ciRunSteps(t, body); strings.Join(got, ",") != strings.Join(fromCI, ",") {
137			t.Errorf("[tasks.ci] steps %v differ from ci.yml steps %v", got, fromCI)
138		}
139	}
140	
141	func TestMiseCIStepsAreDefinedTasks(t *testing.T) {
142		body, all := ciTaskBody(t)
143		for _, s := range ciRunSteps(t, body) {
144			if !all[s] {
145				t.Errorf("[tasks.ci] runs %q, which mise.toml does not define", s)
146			}
147		}
148	}
